import path from "node:path";
import { fileURLToPath } from "node:url";
import type Database from "better-sqlite3";
import { drizzle } from "drizzle-orm/better-sqlite3";
import { migrate } from "drizzle-orm/better-sqlite3/migrator";
import { readMigrationFiles } from "drizzle-orm/migrator";

const here = path.dirname(fileURLToPath(import.meta.url));

/** SQL generated by `pnpm db:generate` from src/db/schema.ts. */
export const migrationsFolder = path.resolve(here, "../../drizzle");

const MIGRATIONS_TABLE = "__drizzle_migrations";

function hasTable(sqlite: Database.Database, name: string) {
  return Boolean(sqlite.prepare("SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?").get(name));
}

/**
 * Databases created before migrations existed already hold the baseline schema
 * (it was created with CREATE TABLE IF NOT EXISTS). Record the baseline as applied
 * so only the later migrations run on them.
 */
function adoptLegacyDatabase(sqlite: Database.Database, folder: string) {
  if (hasTable(sqlite, MIGRATIONS_TABLE) || !hasTable(sqlite, "settings")) return false;
  const [baseline] = readMigrationFiles({ migrationsFolder: folder });
  if (!baseline) return false;
  sqlite.exec(`CREATE TABLE IF NOT EXISTS "${MIGRATIONS_TABLE}" (id SERIAL PRIMARY KEY, hash text NOT NULL, created_at numeric)`);
  sqlite.prepare(`INSERT INTO "${MIGRATIONS_TABLE}" ("hash", "created_at") VALUES (?, ?)`).run(baseline.hash, baseline.folderMillis);
  return true;
}

export function runMigrations(sqlite: Database.Database, folder = migrationsFolder) {
  // Table rebuilds drop and rename parents; with enforcement on, SQLite would cascade those drops into the children.
  // The pragma is ignored inside a transaction, so it has to be switched here, around the migrator.
  sqlite.pragma("foreign_keys = OFF");
  try {
    const adopted = adoptLegacyDatabase(sqlite, folder);
    migrate(drizzle(sqlite), { migrationsFolder: folder, migrationsTable: MIGRATIONS_TABLE });
    const violations = sqlite.pragma("foreign_key_check") as { table: string; parent: string }[];
    if (violations.length > 0) {
      const sample = violations
        .slice(0, 5)
        .map((row) => `${row.table} -> ${row.parent}`)
        .join(", ");
      throw new Error(`Database has ${violations.length} rows with broken references (${sample}).`);
    }
    return { adopted };
  } finally {
    sqlite.pragma("foreign_keys = ON");
  }
}
